{
  "packet_id": "H6-T02-3",
  "claim_id": "C043",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C043.component",
    "value": "Observation duration and the precision requirement should be set before testing using available overnight volume and the smallest operationally meaningful improvement.",
    "scope": "Prospective basis for evidence collection and precision planning.",
    "provenance": {
      "refs": [
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the prospective planning requirement and both substantive inputs, with uncertainty required if the safe observation window supplies insufficient evidence."
    }
  },
  "signal_basis": {
    "component_id": "C043.signal_basis",
    "value": "The bounded concurrency-step experiment tracks the fraction of exports exceeding one hour and completion-time estimates that include unfinished exports. The roughly five-percent slow-export rate can make short tests uninformative, supporting advance planning of observation duration and precision around available volume and meaningful improvement.",
    "scope": "Prospective overnight evidence collection. These measurements have not yet been obtained; insufficient evidence within the safety window requires reporting uncertainty rather than extending exposure unsafely.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P033",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle supplies the experiment, relevant measurements, rarity-based limitation, planning inputs, safety constraint, and prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C043.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a bounded planning requirement; no unresolved empirical relation is needed to license it."
    }
  },
  "rationale": "Available export volume determines how much evidence an observation window can collect, while the smallest meaningful improvement informs the precision needed for a useful decision. With infrequent slow exports, setting these requirements before testing is warranted. The claim does not promise that sufficient precision is achievable within the safe window.",
  "uncertainty": "The packet does not establish a numerical duration or achievable precision. Those remain planning quantities to determine and do not undermine the stated requirement.",
  "anomalies": []
}
